ENA_st.name='ENA'; 
ENA_st.lat=39.0916;
ENA_st.lon=-28.0257;
ENA_st.alt=30;
ENA_st.env='coast';
ENA_st.footp='Mx';
%%
% ENA read from importfile

ENA_rd_h.Properties.DimensionNames{1}='Time';
names_rd=fieldnames(ENA_rd_h);
for i=1:length(names_rd)-3
    ENA_rd_h.(names_rd{i})( ENA_rd_h.(names_rd{i})>900)=NaN;
end
ENA_rd=retime(ENA_rd_h,'daily',@nanmedian);
%%
datevec(ENA_rd.Time(1)) %2013 oct %[output:2e25ac6a]
datevec(ENA_rd.Time(end)) %2025 %[output:0a087701]
prctile(ENA_rd.U0_S11,[5 50 95]) %95%=64% compute dry %[output:361498c1]
prctile(ENA_rd.U1_S11,[5 50 95]) %[output:126458d9]
plotFigControl(ENA_rd,ENA_st.name); %[output:76eca6c4]
%%
% BP detection for scat coef and backscat

names_sc={ 'BsG0_S11', 'BsG1_S11'};
break_ENA_scat_BP=change_point_analysis_Def(ENA_rd,names_sc,0.05,'ENA','scattering'); %[output:3047182c] %[output:974e1a58] %[output:24b1fdc8] %[output:11f0b977]
T_ENA_scat_BP=make_table_breakpoints_def(break_ENA_scat_BP); %[output:5e250fec] %[output:737f9c43]

names_bsc={ 'BbsG0_S11', 'BbsG1_S11'};
break_ENA_bscat_BP=cACode line 30 has output break_ENA_bscat_BP=change_point_analysis_Def(ENA_rd,names_bsc,0.05,'ENA','Backscattering'); %[output:6d11c105] %[output:8403dd9a] %[output:2909c19e] %[output:32c03405]
ange_point_analysis_Def(ENA_rd,names_bsc,0.05,'ENA','Backscattering');
T_ENA_bscat_BP=make_table_breakpoints_def(break_ENA_bscat_BP); %[output:0749b88b] %[output:6118c3ea] %[output:2494e4a8]
%%
% BP detection for abs
names_abs={'BaG0_A11','BaG1_A11'};%{'BaB0_A11','BaG0_A11','BaR0_A11'};
break_ENA_abs_BP=change_point_analysis_Def(ENA_rd,names_abs,0.05,'ENA','Absorption'); %[output:8d0eac02] %[output:54235100] %[output:3729d54d] %[output:184c7ab4]
T_ENA_abs_BP=make_table_breakpoints_def(break_ENA_abs_BP);
%%
lambdaSC=[450;550;700];
lambdaAE=[470;522;660];

names_neph0={'BsB0_S11', 'BsG0_S11', 'BsR0_S11','BbsB0_S11','BbsG0_S11','BbsR0_S11'};
ENA_expS0=compute_exp_D(ENA_rd,names_neph0,lambdaSC);
names_neph1={'BsB1_S11', 'BsG1_S11', 'BsR1_S11','BbsB1_S11','BbsG1_S11','BbsR1_S11'};
ENA_expS1=compute_exp_D(ENA_rd,names_neph1,lambdaSC);
ENA_expS=outerjoin(ENA_expS0,ENA_expS1);

names_abs={'BaB0_A11','BaG0_A11','BaR0_A11'};
ENA_expA=compute_exp_D(ENA_rd,names_abs,lambdaAE);
ENA_cal=outerjoin(ENA_expS,ENA_expA);

ENA_cal.SSAG0=ENA_rd.BsG0_S11./(ENA_rd.BsG0_S11+ENA_rd.BaG0_A11);
ENA_cal.SSAG1=ENA_rd.BsG1_S11./(ENA_rd.BsG1_S11+ENA_rd.BaG1_A11);

plotFigControl_cal(ENA_cal, ENA_st.name); %[output:8389aa9c] %[output:541375b8] %[output:039f5e22]

% problem of expA==0
ENA_cal.expA_bg(ENA_cal.expA_bg==0)=NaN;
ENA_cal.expA_br(ENA_cal.expA_br==0)=NaN;
ENA_cal.expA_gr(ENA_cal.expA_gr==0)=NaN;
%%
% BP detection for expS, Backscat fraction, expA and SSA

names_exps={'expS_bg_ENA_expS0','expS_bg_ENA_expS1'};
break_ENA_exps_BP=change_point_analysis_Def(ENA_cal,names_exps,0.05,'ENA','scattering exp'); %[output:4cfb5ac2] %[output:8b1c553d] %[output:74f394d3] %[output:186bd0e6]
T_ENA_exps_BP=make_table_breakpoints_def(break_ENA_exps_BP); %[output:719069a7] %[output:4d0e83e5]

names_exps={'expA_bg'};
break_ENA_expa_BP=change_point_analysis_Def(ENA_cal,names_exps,0.05,'ENA','absorption exp'); %[output:6051faf0] %[output:8be8c03a]
T_ENA_expa_BP=make_table_breakpoints_def(break_ENA_expa_BP); %[output:30b241a7]

names_BbF={'BbsFg_ENA_expS0','BbsFg_ENA_expS1'};
break_ENA_BbF_BP=change_point_analysis_Def(ENA_cal,names_BbF,0.05,'ENA','backscat fraction'); %[output:011247f3] %[output:3376ea1f] %[output:11c3b61f] %[output:45fff0a1]
T_ENA_BbF_BP=make_table_breakpoints_def(break_ENA_BbF_BP);

names_SSA={'SSAG0','SSAG1'};
break_ENA_SSA_BP=change_point_analysis_Def(ENA_cal,names_SSA,0.05,'ENA','SSA'); %[output:6fceb742] %[output:18cd856f] %[output:4eb2b674] %[output:239f20cb]
T_ENA_SSA_BP=make_table_breakpoints_def(break_ENA_SSA_BP);
%%
ENA_tr=outerjoin(ENA_rd,ENA_cal);
ENA_tr.y=year(ENA_tr.Time);
names=fieldnames(ENA_tr);
% begin at the beginning of a year:sc: 2014 ,abs PM1: 2016
%end: 2025 (October)
P=timerange('2014-01-01','2026-01-01');
ENA_tr=ENA_tr(P,:);

P1=timerange('2014-01-01','2016-01-01');
names_abs1=names(endsWith(names,"1_A11"));
for i=1:length(names_abs1)
    ENA_tr.(names_abs1{i})(P1)=NaN;
end

c= startsWith(names,["Tin";"T1"; "T0";"P";"Q"]) | contains(names,["B0_";"R0_";"B1_";"R1_";"br"; "gr"]);
N=names(c);
for i=1:length(N)-3
    ENA_tr.(N{i})=[];
end

names=fieldnames(ENA_tr);
%%


ENA_tr.expA_br=[];
ENA_tr.expA_gr=[];

ENA_tr.BbsFb_ENA_expS0=[];
ENA_tr.BbsFr_ENA_expS0=[];
ENA_tr.BbsFb_ENA_expS1=[];
ENA_tr.BbsFr_ENA_expS1=[];

names=fieldnames(ENA_tr);
%%
[ENA_result_MK,ENA_result_LMSlog,ENA_result_LMSlin]=all_trend_STN(ENA_tr,ENA_st); %[output:2a6111c8] %[output:62dbd801] %[output:50178c91] %[output:9ecb115b] %[output:7dff1a9e] %[output:2972a75a] %[output:510ccece] %[output:78c24984] %[output:1297889e] %[output:6f17efaf] %[output:74dd9c44] %[output:19efbdcf] %[output:07480fb1] %[output:7dd4c9de] %[output:0144ec69] %[output:43f0a541] %[output:4857cde0] %[output:96b03393] %[output:8f4922f2] %[output:7d3e31d6] %[output:3d35357c] %[output:896321a2] %[output:80831daa] %[output:3f651cac] %[output:785def69] %[output:51830fc6] %[output:3a9992d2] %[output:998ce697] %[output:2f0986e7] %[output:256a030f] %[output:15b09152] %[output:1250d68a] %[output:5f86c640] %[output:79b4cded] %[output:3a2166a3] %[output:30a948e6] %[output:775d284d] %[output:1790d2a0] %[output:77679222] %[output:6d9aad95] %[output:9db6eea0] %[output:7468e184] %[output:80923927] %[output:20538227] %[output:9b328656] %[output:487eb827] %[output:86f3f282] %[output:80173628] %[output:21d7d5de] %[output:15c9d8de] %[output:5219abe8] %[output:947f089d] %[output:4e8fef01] %[output:3837c240] %[output:73b90d89] %[output:9a6b548b] %[output:2479ff4e] %[output:59daa91c] %[output:64997f54] %[output:8cc96571] %[output:56ea691d] %[output:13008fb2] %[output:64226610] %[output:0d05d827] %[output:39864c53] %[output:07a4cbf5] %[output:3783ba59] %[output:374f5004] %[output:8ad4b148] %[output:6efb4804] %[output:5a021b1b] %[output:816f9538] %[output:4a3aae48] %[output:561fbfeb] %[output:9cba6ffe] %[output:5c6ea6f6] %[output:79383084] %[output:06217860] %[output:1f81bf06] %[output:418b0784] %[output:0d8ffa41] %[output:37e9813c]

writetable(ENA_result_MK,'ENA_res_MK_present_10y.txt'); %, 'delimiter',',' )
writetable(ENA_result_LMSlog,'ENA_res_LMSlog.txt'); 
writetable(ENA_result_LMSlin,'ENA_res_LMSlin.txt'); 
plot_10y_in_two(ENA_result_MK, ENA_st,'y'); %[output:47918f5e] %[output:3baac20f]
%%
 timetable_to_netcdf(ENA_tr,'ENA_tr_def.nc'); %[output:985a63c7]



